import (
	"fmt"
	"strconv"
	"strings"
)

type op func(*vm) error

type vm struct {
	stack []int
	defs  map[string]op
}

func (v *vm) push(n int) { v.stack = append(v.stack, n) }

func (v *vm) pop() (int, error) {
	if len(v.stack) == 0 {
		return 0, fmt.Errorf("empty stack")
	}
	n := v.stack[len(v.stack)-1]
	v.stack = v.stack[:len(v.stack)-1]
	return n, nil
}

func (v *vm) apply2(f func(a, b int) int) error {
	b, err := v.pop()
	if err != nil {
		return err
	}
	a, err := v.pop()
	if err != nil {
		return err
	}
	v.push(f(a, b))
	return nil
}
```

