	v.stack = append(v.stack, n)
}

func (v *vm) pop() (int, error) {
	if len(v.stack) == 0 {
		return 0, fmt.Errorf("empty stack")
	}
	n := v.stack[len(v.stack)-1]
	v.stack = v.stack[:len(v.stack)-1]
	return n, nil
}

