func binop(f func(a, b int) int) op {
	return func(v *vm) error {
		b, err := v.pop()
		if err != nil {
			return err
		}
		a, err := v.pop()
		if err != nil {
			return err
		}
		v.push(f(a, b))
		return nil
	}
}

